[CmdletBinding()]
param([Parameter(Mandatory)][string]$PlanCsv,[Parameter(Mandatory)][string[]]$ApprovedRoots,[string]$OutputJson)
$ErrorActionPreference='Stop';$rows=@(Import-Csv -LiteralPath $PlanCsv);$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$targets=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);[long]$bytes=0
function Under([string]$p){$full=[IO.Path]::GetFullPath($p).TrimEnd('\');foreach($root in $ApprovedRoots){$r=[IO.Path]::GetFullPath($root).TrimEnd('\');if($full.Equals($r,[StringComparison]::OrdinalIgnoreCase)-or$full.StartsWith($r+'\',[StringComparison]::OrdinalIgnoreCase)){return $true}};return $false}
foreach($r in $rows){foreach($c in @('SourcePath','TargetPath','SizeBytes','ModifiedUtc')){if(-not$r.PSObject.Properties[$c]-or[string]::IsNullOrWhiteSpace([string]$r.$c)){throw "Missing required column/value: $c"}};$s=[IO.Path]::GetFullPath($r.SourcePath);$t=[IO.Path]::GetFullPath($r.TargetPath);if(-not$seen.Add($s)){throw "Duplicate source: $s"};if(-not$targets.Add($t)){throw "Duplicate target: $t"};if(-not(Under $t)){throw "Target outside approved roots: $t"};if(-not(Test-Path -LiteralPath $s -PathType Leaf)){throw "Missing source: $s"};if([IO.FileInfo]::new($s).Length-ne[long]$r.SizeBytes){throw "Source size drift: $s"};$bytes+=[long]$r.SizeBytes}
$report=[ordered]@{status='valid';rows=$rows.Count;totalBytes=$bytes;validatedAt=(Get-Date).ToString('o')};if($OutputJson){[IO.File]::WriteAllText($OutputJson,($report|ConvertTo-Json),[Text.UTF8Encoding]::new($false))};$report|ConvertTo-Json
